#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;


const int N = 10010;


vector<int> son[N];


int happy[N];


int dp[N][2];


bool hasFather[N];



void dfs(int u)
{
    // 选择u
    dp[u][1]=happy[u];


    // 不选择u
    dp[u][0]=0;



    for(int v:son[u])
    {
        dfs(v);



        // u不出征
        dp[u][0]+=max(
            dp[v][0],
            dp[v][1]
        );



        // u出征
        dp[u][1]+=dp[v][0];
    }
}



int main()
{
    int n;

    cin >> n;



    for(int i=1;i<=n;i++)
    {
        cin >> happy[i];
    }



    for(int i=0;i<n-1;i++)
    {
        int l,k;

        cin >> l >> k;


        son[k].push_back(l);


        hasFather[l]=true;
    }



    int root=1;


    while(hasFather[root])
        root++;



    dfs(root);



    cout << max(
        dp[root][0],
        dp[root][1]
    );


    return 0;
}
